using UnityEngine;
using UnityEditor;
using System;
using System.IO;
using ConRoi.Investigation.V36.R103;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (!EditorApplication.isPlaying)
                throw new Exception("Play required");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            s.SaveDirectoryOverride = Path.GetFullPath("Test/KetQua/investigation_r103/visual-profile");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.ShowUtility();
            w.position = new Rect(0, 0, 1536, 918.4f);
            w.Focus();
            s.Acquire("phone");
            s.Acquire("clip");
            s.OpenPage("clip");
            s.UpdateClip();
            ScreenCapture.CaptureScreenshot("Test/BangChung/investigation_r103/clip-unity-first.png");
            r.Log("Private visual fixture, not route progress. Actor=" + s.clipTu.localPosition + " camera=" + s.clipCamera.transform.localPosition + " clip=" + s.repairEventMotion.length);
        }
    }
}

